/**
 * @summary Retrieve the OpenAPI document
 */
export const getOpenApiDoc = async (options?: RequestInit): Promise<getOpenApiDocResponse> => {
  const res = await customFetch(getGetOpenApiDocUrl(),
    {
      ...options,
      method: 'GET',
    },
  );

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getOpenApiDocResponse['data'] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as getOpenApiDocResponse;
};

