export const getGetItemUrl = (itemId: string, params?: GetItemParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/v1/entities/items/${itemId}?${stringifiedParams}`
    : `/v1/entities/items/${itemId}`;
};

/**
 * @summary Retrieve a single Wikibase Item by ID
 */
export const getItem = async (
  itemId: string,
  params?: GetItemParams,
  options?: RequestInit,
): Promise<getItemResponse> => {
  const res = await customFetch(getGetItemUrl(itemId, params),
    {
      ...options,
      method: 'GET',
    },
  );

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getItemResponse['data'] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as getItemResponse;
};

